head.script:
window.getWpGA4Cookie = function(name) {
    match = document.cookie.match(new RegExp(name + '=([^;]+)'));
    if (match) return decodeURIComponent(match[1].replace(/\+/g, ' ')) ;
};

    window.ga4AllowServices = false;
var isCookieRestrictionModeEnabled = 0,
    currentWebsiteId = 7,
    cookieRestrictionName = 'user_allowed_save_cookie';

if (isCookieRestrictionModeEnabled) {
    allowedCookies = window.getWpGA4Cookie(cookieRestrictionName);

    if (allowedCookies !== undefined) {
        allowedWebsites = JSON.parse(allowedCookies);

        if (allowedWebsites[currentWebsiteId] === 1) {
            window.ga4AllowServices = true;
        }
    }
} else {
    window.ga4AllowServices = true;
}

if (window.ga4AllowServices) {
    window.dataLayer = window.dataLayer || [];
                var dl4Objects = [{"pageName":"404 Not Found - Timpte Equipment Trailers","pageType":"other","google_tag_params":{"ecomm_pagetype":"other"}}];
    for (var i in dl4Objects) {
        window.dataLayer.push({ecommerce: null});
        window.dataLayer.push(dl4Objects[i]);
    }
                var wpGA4Cookies = ['wp_ga4_user_id','wp_ga4_customerGroup'];
    var orderCustomerGroupCookie = 'wp_ga4_customerGroupForOrder';
    var regularCustomerGroupCookie = 'wp_ga4_customerGroup';
    var orderCustomerGroupValue = window.getWpGA4Cookie(orderCustomerGroupCookie);

    wpGA4Cookies.map(function (cookieName) {
        var cookieValue = window.getWpGA4Cookie(cookieName);
        if (cookieValue) {
            var dl4Object = {};
            var cookieKey = cookieName.replace('wp_ga4_', '');
            // Use order customerGroup cookie instead of regular customerGroup cookie if it exists
            if (cookieName === regularCustomerGroupCookie && orderCustomerGroupValue) {
                dl4Object[cookieKey] = orderCustomerGroupValue;
            } else {
                dl4Object[cookieKey] = cookieValue;
            }
            window.dataLayer.push(dl4Object);
        }
    });
}

