// Fix to prevent 'no reCaptcha Token' error while slow site loading.
// Submit button should catch am-captcha.js initialization8 first
(function () {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', onReadyStateListener);
    } else {
        onReadyState();
    }

    function onReadyStateListener() {
        onReadyState();
    }

    function onReadyState (formsOnPage) {
        if (typeof formsOnPage === 'undefined') {
            let formsToProtect = "form\u005Baction\u002A\u003D\u0022amasty_customform\u002Fform\u002Fsubmit\u0022\u005D";
            let forms = formsToProtect.split(',');

            formsOnPage = [];
            forms.forEach(form => {
                let existingForm = form ? document.querySelectorAll(form) : [];

                if (existingForm.length) {
                    formsOnPage.push(existingForm);
                }
            })
        }

        formsOnPage.forEach(form => {
            let submit = form[0].querySelector('[type="submit"]');
            if (submit) {
                let isAlreadyDisabled = submit.getAttribute('disabled');

                if (!isAlreadyDisabled) {
                    submit.setAttribute('disabled', true);
                    submit.setAttribute('am-captcha-protect', true);
                }
            }
        })
    }

                    window.addEventListener('amform-elements-rendered', function (event) {
        onReadyState([event.detail.form]);
    });
    window.addEventListener('am-recaptcha-submit-event', function (event) {
        onReadyState([event.detail.form]);
    });
                })();

    (function () {
        function moveFooterButton() {
            var holder = document.querySelector('.footer-button-holder');
            var target = document.querySelector('.footer-button-target');

            if (!holder || !target || target.contains(holder)) {
                return;
            }

            target.appendChild(holder);
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', moveFooterButton);
        } else {
            moveFooterButton();
        }
    })();

window.ga4ParentVsChild = 'parent';
window.ga4VariantEnabled = '0';
require(['jquery','weltpixel_ga4_persistentLayer','weltpixel_ga4_gtm', 'Magento_Customer/js/customer-data'],
    function ($, wpGa4PersDl ,wpGa4gtm, customerData) {
        if (window.ga4AllowServices) {
            $(document).ajaxComplete(function (event, xhr, settings) {
                if (settings.url.search('/customer\/section\/load/') > 0) {
                    var response = xhr.responseJSON;
                    if (response.wp_ga4) {
                        var dataLayerData = $.parseJSON(response.wp_ga4.datalayer);
                        for (index in dataLayerData) {
                            window.dataLayer.push({ecommerce: null});
                            window.dataLayer.push(dataLayerData[index]);
                        }
                    }
                }
            });
            var wpPersDlOptions = {'storageExpiryTime': 30 };
            var wpGtmOptions = {
                'enabled': 0,
                'persDataLayer': wpGa4PersDl,
                'disableDatalayerEvents': 1,
                'serverSidePromotionViewEnabled': 0,
                'serverSidePromotionClickEnabled': 0                    };
            wpGa4PersDl.init(wpPersDlOptions);
            wpGa4gtm.trackPromotion(wpGtmOptions);
        }
    });

window.amlazy = function() {
    if (typeof window.amlazycallback !== "undefined") {
        setTimeout(window.amlazycallback, 500);
        setTimeout(window.amlazycallback, 1500);
    }
}

window.addEventListener('load', () => {
    const addStylesNode = document.getElementById("deferred-css");
    const replacement = document.createElement("div");
    replacement.innerHTML = addStylesNode.textContent;
    document.body.appendChild(replacement);
    addStylesNode.parentElement.removeChild(addStylesNode);
});
